def terrain(g,kind,x,y):
    if kind=='T0':return 0.
    if kind=='T1':return .05*x
    if kind=='T2':return .03*x+.02*y
    if kind=='T3':return .5*g.math('SINE',x/30)*g.math('COSINE',y/25)
